CREATE TRIGGER audit_field_reports_insert AFTER INSERT ON field_reports FOR EACH ROW INSERT INTO audit_logs (table_name, record_id, operation, actor_id, new_data) VALUES ('field_reports', NEW.id, 'INSERT', NULLIF(@app_user_id, ''), JSON_OBJECT('id',NEW.id,'barangay_id',NEW.barangay_id,'farmer_id',NEW.farmer_id,'crop_type_id',NEW.crop_type_id,'area_ha',NEW.area_ha,'planting_date',NEW.planting_date,'planting_method',NEW.planting_method,'latitude',NEW.latitude,'longitude',NEW.longitude,'notes',NEW.notes,'status',NEW.status,'remarks',NEW.remarks,'submitted_by',NEW.submitted_by,'reviewed_by',NEW.reviewed_by,'reviewed_at',NEW.reviewed_at,'created_at',NEW.created_at));
